from pathlib import Path
from html import escape as e
import re
items=[
('logo-designing','Logo Designing','A recognisable identity for your business','Your logo is often the first visual introduction to your business. We develop a mark that reflects your positioning and stays clear across a website, stationery, packaging and signage.',['Discuss your audience, business personality and where the logo will appear.','Explore symbol, wordmark and combination-mark directions with considered typography.','Refine proportion, spacing and colour, then check small-size and monochrome use.'],['Primary logo and agreed alternate arrangements.','Colour and monochrome exports in agreed vector and raster formats.','Basic guidance on clear space, colours and appropriate use.'],'New businesses, rebrands and organisations with inconsistent visual identities.','Your exact business name, tagline if required, audience, competitors, preferred direction and existing trademarks.','Trademark searches and registration are separate; a logo concept is not a legal clearance.'),
('visiting-card-designing','Visiting Card Designing','Make every introduction feel considered','A business card should make it easy to remember you and get in touch. We balance brand recognition with clear contact details, suitable type sizes and a layout that works at actual print size.',['Organise names, roles, phone numbers, website and contact information by importance.','Develop front and back layouts aligned with your logo and brand palette.','Review stock, finishing ideas, trim, safe areas and printer requirements.'],['Approved front and back artwork at the agreed card size.','Print-ready PDF with the printer’s required bleed and colour setup.','Named variants for the number of team members agreed in the brief.'],'Sales teams, consultants, retail businesses and professional networking.','Logo artwork, verified contact details, team-member list and printer specifications.','Printing, special finishes and additional staff versions are quoted separately unless included.'),
('letterhead-designing','Letterhead Designing','Bring consistency to business correspondence','Well-designed letterheads make quotations, letters and formal communication feel part of the same brand. We build a clean hierarchy around your identity while leaving practical space for document content.',['Arrange the logo, business name and approved contact information.','Plan margins, header and footer areas for everyday use.','Check the layout with sample short and long letters.'],['Approved letterhead artwork in the agreed paper size.','Print-ready PDF and a digital template if included in scope.','Basic placement and usage guidance for your team.'],'Companies preparing proposals, business letters and formal correspondence.','Logo, official company details, required disclosures, paper size and software used by staff.','Editable Word templates and printing require explicit agreement in the proposal.'),
('brochure-designing','Brochure Designing','Tell your business story with clarity','A brochure gives prospects a guided introduction to your products or services. We shape the reading order so people can understand your offer, compare information and find the next step without feeling overwhelmed.',['Plan a page or panel structure around audience questions and your objective.','Combine supplied copy, photography, headings and calls to action.','Review folds, pagination, image quality and print specifications.'],['A layout plan and agreed creative direction.','Approved brochure artwork for the contracted page or panel count.','Print-ready PDF and a screen-friendly PDF when included.'],'Company profiles, product launches, service introductions and sales presentations.','Final copy, brand assets, images, page count, format, distribution method and printer requirements.','Copywriting, photography, translation and printing can be scoped separately.'),
('pamphlet-designing','Pamphlet Designing','A clear message in a compact format','Pamphlets work best when they answer one main customer need. We turn a focused offer or message into a compact design with a strong headline, useful supporting information and a visible action.',['Identify the offer, audience and distribution context.','Build a reading hierarchy across the agreed single or folded format.','Check contact details, offer conditions, image quality and readability.'],['Approved artwork for the agreed sides and folds.','Print-ready PDF with confirmed size and bleed.','Digital sharing version if requested in the brief.'],'Local promotions, awareness campaigns, events and service launches.','Offer wording, validity dates, terms, contact details, logo and desired print size.','Extra language versions, copy changes after approval and distribution are separate unless agreed.'),
('catalogue-designing','Catalogue Designing','Help customers explore your product range','A catalogue needs a consistent information system as well as attractive pages. We organise categories, product images and specifications into a layout that helps buyers compare options and locate relevant products.',['Agree category order, navigation and a repeatable product layout.','Place images, product codes, specifications and supplied pricing consistently.','Review product-data accuracy, page flow and output requirements.'],['An agreed catalogue structure and sample-page design.','Laid-out pages for the contracted products and page count.','Approved print-ready and/or digital PDF outputs.'],'Manufacturers, distributors, wholesalers and businesses with a broad product range.','A clean product spreadsheet, approved photos, categories, descriptions, prices and publication date.','Product-data entry, image retouching and future price revisions are scoped by volume.'),
('social-post-design','Social Post Design','A consistent visual voice in the feed','Social graphics should make your message easy to recognise and understand quickly. We design platform-appropriate static posts and carousels that use a coherent visual system while leaving room for different campaign messages.',['Define content themes, audience, platform and campaign objective.','Design typography, imagery and layouts that remain readable on a phone.','Adapt approved concepts to the sizes and placements in your brief.'],['The agreed number of static graphics or carousel panels.','Platform-sized image exports.','Reusable templates or editable source files when contracted.'],'Brands sharing educational content, offers, announcements and product stories.','Approved captions or key messages, logo, images, content calendar and required sizes.','Posting, community management, advertising spend and ongoing content planning are separate services.'),
('handbill-designing','Handbill Designing','Make local promotions easy to act on','Handbills are designed for a quick read during local distribution. We give your offer a strong focal point, make essential details easy to find and keep the format practical for the printing quantity and distribution plan.',['Prioritise the headline, offer, location and contact action.','Choose a clear layout suitable for the intended paper size.','Check terms, validity dates, directions and QR destinations if supplied.'],['Approved single- or double-sided handbill artwork.','Print-ready PDF to the agreed printer specifications.','A digital preview for final checking before production.'],'Store openings, neighbourhood campaigns, events and time-sensitive offers.','The final offer, location, dates, contact information, quantity and printer details.','Printing and physical distribution are not included unless specifically quoted.'),
('festival-greetings','Festival Greetings','Celebrate occasions with a thoughtful brand presence','Seasonal greetings should feel warm and appropriate to the occasion. We combine your brand identity with a relevant visual direction and carefully reviewed wording for customers, colleagues or business partners.',['Agree the occasion, audience, language and tone.','Develop a suitable festive concept with restrained brand placement.','Review dates, spelling, cultural context and intended sharing channels.'],['Approved greeting artwork in the contracted formats.','Social, messaging or print exports as agreed.','Language and name variations included in the brief.'],'Businesses planning festive communication, client greetings and seasonal announcements.','Festival list, greeting text, preferred languages, logo and publishing dates.','Animation, custom illustration, translation and bulk personalised variants require separate scope.'),
('animated-video','Animated Video','Explain your message through purposeful motion','Animation can make a service, product or idea easier to follow. We plan the narrative before production, then use appropriate motion, pacing and sound to support the message rather than distract from it.',['Develop or refine the script and define the intended audience action.','Agree a storyboard, visual style and key frames before animation.','Produce motion, add approved audio and review pacing, subtitles and exports.'],['Approved script/storyboard stages as included in the proposal.','Finished video in the agreed duration, aspect ratios and resolution.','Subtitle files, thumbnails or cutdowns where contracted.'],'Explainers, product introductions, social campaigns and brand presentations.','Objective, key messages, duration, platform, brand assets, voice-over language and references.','Voice-over, music licences, 3D work, source files and extra revisions must be agreed upfront.'),
('ai-video','AI Video','Explore creative possibilities with human direction','AI-assisted video combines generated visual material with editorial judgement. We begin with a clear concept, evaluate whether AI suits the subject and review every sequence for consistency, accuracy and brand suitability.',['Define the concept, script, shot list and acceptable visual style.','Generate and select candidate clips, then edit them into a coherent sequence.','Review visual artefacts, continuity, factual claims, audio and final formats.'],['Agreed concept and production direction.','Edited video at the contracted duration and output sizes.','A review stage for approved content and any agreed AI disclosure.'],'Concept-led brand stories, stylised product scenes and exploratory campaign visuals.','Brief, approved claims, brand assets, usage context and any consent or rights for supplied likenesses.','Exact likeness, text rendering and scene continuity may require alternative production. Usage rights and tool restrictions are reviewed for the project; real-person likenesses require permission.')]
base=Path('branding-design.html').read_text(encoding='utf-8'); header=base[base.index('<header'):base.index('</header>')+9]; footer=base[base.index('<footer'):base.index('</footer>')+9]
css='''<link rel="stylesheet" href="assets/vendor/bootstrap/bootstrap.min.css"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="digital-marketing.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><link rel="stylesheet" href="responsive.css"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;750;800&display=swap"><link rel="stylesheet" href="theme.css">'''
def shell(title,desc,main):
 return '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+' | Global Advertising Media</title><meta name="description" content="'+e(desc,quote=True)+'">'+css+'</head><body>'+header+main+footer+'<script src="assets/vendor/bootstrap/bootstrap.bundle.min.js"></script><script src="script.js"></script><script src="responsive.js"></script></body></html>'
for slug,title,tag,intro,tasks,outputs,audience,brief,note in items:
 main=f'''<main id="{slug}" class="graphic-detail-page"><section class="graphic-detail-hero"><div class="container"><nav aria-label="Breadcrumb"><a href="index.html">Home</a> / <a href="graphic-design.html">Graphic Design</a> / {e(title)}</nav><span class="eyebrow">GRAPHIC DESIGN &amp; CREATIVE PRODUCTION</span><h1>{e(title)}</h1><p>{e(tag)}</p><a class="btn btn-primary" href="index.html#contact">Discuss your project ↗</a></div></section><section class="section"><div class="container"><div class="graphic-detail-intro"><div><span class="eyebrow">DESIGNED AROUND YOUR MESSAGE</span><h2>{e(tag)}</h2><p>{e(intro)}</p><h3>Who it is for</h3><p>{e(audience)}</p></div><aside class="card"><h2>What to share with us</h2><p>{e(brief)}</p><p>We confirm the scope, timeline, review stages and quote after understanding your requirements.</p></aside></div><div class="graphic-detail-columns"><article class="card"><h2>What the service includes</h2><ul>{''.join('<li>'+e(t)+'</li>' for t in tasks)}</ul></article><article class="card"><h2>What you receive</h2><ul>{''.join('<li>'+e(o)+'</li>' for o in outputs)}</ul></article></div></div></section><section class="section studio-section"><div class="container"><span class="eyebrow">A CLEAR PATH FROM BRIEF TO HANDOVER</span><h2>How your project takes shape</h2><ol class="studio-steps"><li><span class="studio-number">01</span><h3>Understand</h3><p>Discuss the audience, message, formats and practical requirements. Confirm deliverables and responsibilities.</p></li><li><span class="studio-number">02</span><h3>Explore</h3><p>Develop the agreed creative direction and present the concept or layout for your feedback.</p></li><li><span class="studio-number">03</span><h3>Refine</h3><p>Consolidate your feedback, complete the contracted revisions and review the final details together.</p></li><li><span class="studio-number">04</span><h3>Deliver</h3><p>Prepare the approved files for their intended use and confirm the handover requirements.</p></li></ol><div class="conversation-note"><strong>Agree the details before production</strong><p>{e(note)}</p></div></div></section><section class="section"><div class="container"><h2>Questions about {e(title.lower())}</h2><details class="faq-item"><summary>How are the cost and timeline decided?</summary><p>The quote depends on the brief, number of concepts or pages, formats, asset readiness and review schedule. We confirm a timeline after agreeing the scope.</p></details><details class="faq-item"><summary>Can you match our existing brand?</summary><p>Yes. Share your brand guidelines, logo files and approved examples so the design can follow your established identity. Any proposed changes are discussed before approval.</p></details><details class="faq-item"><summary>Are editable files and revisions included?</summary><p>The proposal specifies the included revision rounds, final formats and editable source files. Additional variants or changes after approval are quoted separately.</p></details><div class="studio-invitation"><div><h3>Tell us what you want to create.</h3><p>Share your brief and intended use so we can recommend a practical next step.</p></div><a class="btn btn-primary" href="index.html#contact">Start a conversation ↗</a></div><h2 class="mt-5">Explore more graphic design services</h2><nav class="graphic-related" aria-label="Related graphic design services">{''.join('<a href="'+x[0]+'.html">'+e(x[1])+'</a>' for x in items if x[0]!=slug)}</nav></div></section></main>'''
 Path(slug+'.html').write_text(shell(title,intro,main),encoding='utf-8')
# Retain the overview and make its cards lead to the dedicated pages.
p=Path('graphic-design.html'); s=p.read_text(encoding='utf-8')
for slug,*_ in items:
 pattern=r'(<article\b[^>]*id="'+slug+r'"[\s\S]*?<a\b[^>]*href=")([^"]+)(")'
 s=re.sub(pattern,lambda m:m[1]+slug+'.html'+m[3],s,count=1)
s=s.replace('Enquire about this service ↗','Explore this service ↗')
p.write_text(s,encoding='utf-8')
# Update existing anchor-only menus, or insert the menu on pages that lack it.
menu='<li class="nav-item has-dropdown dropdown graphic-design-nav"><a href="{prefix}graphic-design.html" class="nav-link">Graphic Design</a><button type="button" class="submenu-toggle" data-bs-toggle="dropdown" data-bs-display="static" aria-expanded="false" aria-label="Open Graphic Design menu"><span class="dropdown-arrow" aria-hidden="true"></span></button><ul class="dropdown-menu">'+''.join('<li><a class="dropdown-item" href="{prefix}'+x[0]+'.html">'+e(x[1])+'</a></li>' for x in items)+'</ul></li>'
count=0
for p in Path('.').rglob('*.html'):
 s=p.read_text(encoding='utf-8-sig')
 if '<header' not in s: continue
 out=s
 for slug,*_ in items: out=out.replace('graphic-design.html#'+slug,slug+'.html')
 if 'graphic-design-nav' not in out:
  prefix='../'* (len(p.parts)-1)
  out=out.replace('<!-- Website Designing Dropdown -->',menu.replace('{prefix}',prefix)+'\n<!-- Website Designing Dropdown -->',1)
 if out!=s: p.write_text(out,encoding='utf-8');count+=1
print(f'Created 11 detailed service pages; updated navigation on {count} pages.')
